import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const assets = path.join(root, 'public', 'assets');

const cssFiles = [
  'app-v42.css', 'app-v43.css', 'app-v44.css', 'app-v45.css', 'app-v46.css',
  'app-v47.css', 'app-v48.css', 'app-v49.css', 'app-v50.css', 'app-v51.css',
  'app-v51b.css', 'app-v51c.css', 'app-v52.css', 'app-v53.css', 'app-v54.css',
  'app-v55.css', 'app-v56.css', 'app-v56-cycle-final.css', 'app-v57-reference.css',
  'app-v57-cycle-tune.css', 'app-v57-pivot-match.css', 'app-v57-clarity.css'
];

const jsFiles = [
  'app-v44.js', 'app-v56-gems.js', 'app-v57-pivot-match.js'
];

function bundle(files, output) {
  const body = files.map((name) => {
    const source = fs.readFileSync(path.join(assets, name), 'utf8').trimEnd();
    return `/* ---- ${name} ---- */\n${source}`;
  }).join('\n\n');
  fs.writeFileSync(path.join(assets, output), `/* Generated by scripts/build-dashboard-bundle.mjs. */\n${body}\n`);
  console.log(`${output}: ${files.length} sources`);
}

bundle(cssFiles, 'app-v57-bundle.css');
bundle(jsFiles, 'app-v57-bundle.js');
